R=Path(__file__).resolve().parents[2];O=R/'docs/v5/zoom';O.mkdir(exist_ok=True);profile=R/'work/v5_zoom/Default';profile.mkdir(parents=True,exist_ok=True);(profile/'Preferences').write_text(json.dumps({'partition':{'default_zoom_level':{'x':math.log(2)/math.log(1.2)}}}))
